TLM.f("Tempora/Epi1-3",{"officium":"Feria IV infra Hebdomadam I post Epiphaniam","rule":["vide Epi1-0a","Suffragium=Maria2;Papa,Ecclesiæ;;"],"ruleInherited":["ex Sancti/01-06","Gloria","Credo","Prefatio=Epi","Gloria","Credo","Prefatio=Epi"],"fallback":"Tempora/Epi1-0a","from":{"Introitus":"Tempora/Epi1-0a","Oratio":"Tempora/Epi1-0a","Lectio":"Tempora/Epi1-0a","Graduale":"Tempora/Epi1-0a","Evangelium":"Tempora/Epi1-0a","Offertorium":"Tempora/Epi1-0a","Secreta":"Tempora/Epi1-0a","Communio":"Tempora/Epi1-0a","Postcommunio":"Tempora/Epi1-0a","Commemoratio Oratio":"Tempora/Epi1-0a","Commemoratio Secreta":"Tempora/Epi1-0a","Commemoratio Postcommunio":"Tempora/Epi1-0a"},"sections":{"Introitus":[{"k":"text","la":"In excélso throno vidi sedére virum, quem adórat multitúdo Angelórum, psalléntes in unum: ecce, cujus impérii nomen est in ætérnum"},{"k":"ref","la":"Ps 99:1"},{"k":"text","la":"Jubiláte Deo, omnis terra: servíte Dómino in lætítia."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In excélso throno vidi sedére virum, quem adórat multitúdo Angelórum, psalléntes in unum: ecce, cujus impérii nomen est in ætérnum"}],"Oratio":[{"k":"text","la":"Vota, quǽsumus, Dómine, supplicántis pópuli cœlésti pietáte proséquere: ut et, quæ agénda sunt, vídeant, et ad implénda, quæ víderint, convaléscant."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános."},{"k":"ref","la":"Rom 12:1-5"},{"k":"text","la":"Fratres: Obsecro vos per misericórdiam Dei, ut exhibeátis córpora vestra hóstiam vivéntem, sanctam, Deo placéntem, rationábile obséquium vestrum. Et nolíte conformári huic sǽculo, sed reformámini in novitáte sensus vestri: ut probétis, quæ sit volúntas Dei bona, et benéplacens, et perfécta. Dico enim per grátiam, quæ data est mihi, ómnibus qui sunt inter vos: Non plus sápere, quam opórtet sápere, sed sápere ad sobrietátem: et unicuique sicut Deus divísit mensúram fídei. Sicut enim in uno córpore multa membra habémus, ómnia autem membra non eúndem actum habent: ita multi unum corpus sumus in Christo, sínguli autem alter alteríus membra: in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 71:18 ; 71:3"},{"k":"text","la":"Benedíctus Dóminus, Deus Israël, qui facit mirabília magna solus a sǽculo."},{"k":"text","la":"Suscípiant montes pacem pópulo tuo, et colles justítiam. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 99:1"},{"k":"text","la":"Jubiláte Deo, omnis terra: servíte Dómino in lætítia. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam."},{"k":"ref","la":"Luc 2:42-52"},{"k":"text","la":"Cum factus esset Jesus annórum duódecim, ascendéntibus illis Jerosólymam secúndum consuetúdinem diéi festi, consummatísque diébus, cum redírent, remánsit puer Jesus in Jerúsalem, et non cognovérunt paréntes ejus. Existimántes autem illum esse in comitátu, venérunt iter diéi, et requirébant eum inter cognátos et notos. Et non inveniéntes, regréssi sunt in Jerúsalem, requiréntes eum. Et factum est, post tríduum invenérunt illum in templo sedéntem in médio doctórum, audiéntem illos et interrogántem eos. Stupébant autem omnes, qui eum audiébant, super prudéntia et respónsis ejus. Et vidéntes admiráti sunt. Et dixit Mater ejus ad illum: Fili, quid fecísti nobis sic? Ecce, pater tuus et ego doléntes quærebámus te. Et ait ad illos: Quid est, quod me quærebátis? Nesciebátis, quia in his, quæ Patris mei sunt, opórtet me esse? Et ipsi non intellexérunt verbum, quod locútus est ad eos. Et descéndit cum eis, et venit Názareth: et erat súbditus illis. Et Mater ejus conservábat ómnia verba hæc in corde suo. Et Jesus proficiébat sapiéntia et ætáte et grátia apud Deum et hómines."}],"Offertorium":[{"k":"ref","la":"Ps 99:1; 99:2"},{"k":"text","la":"Jubiláte Deo, omnis terra, servíte Dómino in lætítia: intráte in conspéctu ejus in exsultatióne: quia Dóminus ipse est Deus."}],"Secreta":[{"k":"text","la":"Oblátum tibi, Dómine, sacrifícium vivíficet nos semper et múniat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 2:48; 2:49"},{"k":"text","la":"Fili, quid fecísti nobis sic? ego et pater tuus doléntes quærebámus te. Et quid est, quod me quærebátis? nesciebátis, quia in his, quæ Patris mei sunt, opórtet me esse?"}],"Postcommunio":[{"k":"text","la":"Súpplices te rogámus, omnípotens Deus: ut, quos tuis réficis sacraméntis, tibi étiam plácitis móribus dignánter deservíre concédas."},{"k":"macro","name":"Per Dominum"}],"Commemoratio Oratio":[{"k":"rubric","la":"Pro Octavam Epiphaniæ"},{"k":"text","la":"Deus, qui hodiérna die Unigénitum tuum géntibus stella duce revelásti: concéde propítius; ut, qui jam te ex fide cognóvimus, usque ad contemplándam spéciem tuæ celsitúdinis perducámur."},{"k":"macro","name":"Per eumdem"}],"Commemoratio Secreta":[{"k":"rubric","la":"Pro Octavam Epiphaniæ"},{"k":"text","la":"Ecclésiæ tuæ, quǽsumus, Dómine, dona propítius intuere: quibus non jam aurum, thus et myrrha profertur; sed quod eisdem munéribus declarátur, immolátur et súmitur, Jesus Christus, fílius tuus, Dóminus noster:"},{"k":"macro","name":"Qui tecum"}],"Commemoratio Postcommunio":[{"k":"rubric","la":"Pro Octavam Epiphaniæ"},{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, quæ sollémni celebrámus officio, purificátæ mentis intellegéntia consequámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"b369ce3f7fe42e11":{"t":"Ps 99, 1\nNa uzvišenom prijestolju vidjeh kako sjedi čovjek. Njemu se klanja mnoštvo anđela koji složno pjevaju: Evo onoga koji vlada vječnim kraljevstvom! (Ps 99, 1) Poklikni Bogu, sva zemljo! Služite Gospodinu veselo.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\nNa uzvišenom prijestolju vidjeh kako sjedi čovjek. Njemu se klanja mnoštvo anđela koji složno pjevaju: Evo onoga koji vlada vječnim kraljevstvom!","kn":"Na uzvišenom prijestolju vidjeh gdje sjedi muž, kome se klgnja mnoštvo anđela jednoglasno n pjevajući: evo onoga, kojega je kraljevstvo vječno! (Rs. 99, 1). Pokli'kni Bogu sva zemljo, služite Gospodinu veselo! Slava Ocu . . . Na uzvišenom . .","knRef":"Kniewald 1942, str. 74–75 (snimka 38) (OCR)"},"7099fdc02d57f811":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, prati nebeskom milošću prošnje naroda koji te zaziva, da vidi što treba činiti i da stekne snagu te može vršiti ono što vidi.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"MolimOi Gospodine, prati prošnje naroda, koji se moli, nebeskom mllostivošću, da vide, što treba činiti i da ojačaju, te mogu vršiti ono, što vide, ipo G. n. I. K.","knRef":"Kniewald 1942, str. 76–77 (snimka 39) (OCR)"},"872333974f2a5473":{"t":"Rim 12, 1-5\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: zaklinjem vas milosrđem Božjim da prikažete svoje tijelo kao žrtvu živu, svetu i ugodnu Bogu, da vaše bogoštovlje bude duhovno. Nemojte se izjednačiti s ovim svijetom. Naprotiv, obnovite svoje mišljenje da možete uočiti što je Božja volja, što je dobro, ugodno i savršeno. Po milosti koja mi je dana kažem svakom od vas, da ne cijeni sebe više nego se smije cijeniti, već trijezno prema mjeri vjere koju je Bog kome udijelio. Kao što u jednom tijelu imamo mnogo udova, a svi udovi nemaju istu službu, tako smo mnogi jedno tijelo u Kristu, a svi mi pojedini smo udovi jedan drugome u Kristu Gospodinu našemu.","kn":"Čitanje poslanice bi. Pavla apostola Rimljanima (12, 1-5). Braćo! Zaklinjem vas Božjim milosrđem, da svoja tjelesa prikažete Bogu . kao žrtvu živu, svetu, Bogu dragu, da bude razumna vaša služba. I nemojte se izjednačivati s ovim svijetom, nego se promijenite obnovom svoga uma, da: dokažete, što je po Božjoj volji dobro, ugodno i savršeno. Jer. po milosti, koja mi je dana, kažem svima, koji su među vama: Ne cijenite sebe više nego treba, ■nego se cijenite trijezno i ipo mteri vjere, koju je Bog udijelio pojedincu. Jer kao što imamo mnogo udova u jednomu tijelu, a svi udovi nemaju jedne službe, tako smo mnogi u Kristu jedno tijelo, a pojedini udovi jedan drugomu u Isusu Kristu, Gospodinu našemu. ,","knRef":"Kniewald 1942, str. 76–77 (snimka 39) (OCR)"},"ebdb9d170dee2369":{"t":"Ps 71, 18 i 3\nBlagoslovljen Gospodin Bog Izraelov koji jedini čini divna i velika djela od vijeka. Neka planine osjete mir i bregovi pravdu koju daješ narodu svome.\n\nPs 99, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nPoklikni Bogu, sva zemljo! Služite Gospodinu veselo! <i>Aleluja</i>.","kn":"(Ps. 71, 18, 3). Blagoslovljen Gospodin Bog Izraelov, koji čini velika i divna djela dovijeka. Neka bregovl donesu mir puku Tvome, a brežuljci, pravdu.\n\nAleluja, aleluja (Ps. 99, 1). Poklikni Bogu sva zemljo, služite Gospodinu u radosti, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 76–77 (snimka 39) (OCR)"},"3f677878a41c5a6d":{"t":"Lk 2, 42-52\nSlijedi sveto Evanđelje po Luki. Kad je Isusu bilo dvanaest godina, njegovi roditelji pođu po blagdanskom običaju u Jeruzalem. Kad su prošli blagdani i oni se vraćali, dječak Isus ostade u Jeruzalemu, a da njegovi roditelji nisu znali. Misleći da je među suputnicima, išli su dan hoda, a onda ga stanu tražiti među rođacima i znancima. Ali, kako ga ne nađu, vrate se u Jeruzalem da ga traže. – Poslije tri dana nađu ga u hramu gdje sjedi među učiteljima, kako ih sluša i postavlja pitanja. Svi koji su ga slušali, divili su se njegovoj mudrosti i odgovorima. Kad ga opaze, vrlo se začude. A majka mu reče: »Sine, zašto si nam to učinio? Tvoj otac i ja žalosni smo te tražili.« On im odgovori: »Zašto ste me tražili? Zar niste znali da ja moram biti u onome što pripada mom Ocu?« A oni nisu shvatili njegovih riječi. – On tada pođe s njima i dođe u Nazaret i bio im je poslušan. Njegova je Majka sve ovo čuvala u svom srcu. A Isus je napredovao u mudrosti, dobi i milosti pred Bogom i ljudima.","kn":"t Slijedi sveto Evanđelje po Luki (2, 42-52). Kad je Isusu bilo dvanaest godina, njego.vi ''“''^\"telji po^ đoše po običaju blagdana u Jeruzalem. Kad su prošli, blagdani i oni se vraćali, dječak Isus ostade u Jeruzalemu, a da nijesu znali A jer su mislili, da je s društvom, posli su _dan . hoda i pitali za njega rođake .i ^ ® ne nađoše, vrate se u Jeruza.lem da ga Uaze. poslije tri dana nađu ga u hramu, gdje sjed-i medu uč teljima, kako. ih sluša i pita- I sv'i. koji su ga čuli, dlviU su se njegovoj, mudrosti i odgovorim^ I kad ga opaze, začude se, a, njegova mu maijka sLo, što Si nam tako učinio? Evo, ^ojmte i i, a tražili smo te žalosni! On odgovori. Zašto ste me tražili? Zar nijeste znali. da. jo treba da b«dem u kući svojega Oca? A oni .nijesu razumjeli sto m je kazao. I siđe ,s njima, i dođe a, Nazaret, i bm im ie pokoran. Njegova je majka sve ovo. cuv.^ svom srcu. a IS'US je napredovao, u mudrosti i dooi i milosti kod Boga i ljudi.","knRef":"Kniewald 1942, str. 72–73 (snimka 37) (OCR)"},"4d01621aada35dae":{"t":"Ps 99, 1-2\nPoklikni Bogu, sva zemljo! Služite Gospodinu veselo! Stupite preda nj veselo kličući, jer je samo Bog Gospodin.","kn":"(Ps. 99, 1, 2). Poklikni Bogu sva zemljo, služite Gospodinu veselo! Idite pred lice njegovo s klicanjem, jer je Gospodin sam Bog.","knRef":"Kniewald 1942, str. 76–77 (snimka 39) (OCR)"},"f321c843e76ed500":{"t":"Neka nas vazda oživljuje i brani, Gospodine, žrtva koju ti prinosimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Žrtva, koju smo Ti prinijeli, neka nas, Gospodine, vazda oživljava i štiti, po G. n. I. K.","knRef":"Kniewald 1942, str. 94–95 (snimka 48) (OCR)"},"93e8203b4ea3a0a5":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože: – jer kad se tvoj Jedinorođenac pojavio u našem smrtnom tijelu, on nas je novim svjetlom svoje besmrtnosti obnovio. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje. Uistinu je dostojno 1 (pravedno, pravo i spasonosno, da vazda i svagdje za.hvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, jer nas je Tvoj Jedinorođeni obnovio novim svijetlom svoj® neumrlos'ti. kad se ukazao u biti naše smrtnosti. I toga redi pjevamo pjesmu slavi Tvojoj s anđelima i s arkainđelima, s prijestolima i gospodstvima, sa svom silom nebeske vojske bez prestanka govoreći:","knRef":"Kniewald 1942, str. 74–75 (snimka 38) (OCR)"},"6741fc27d78054a2":{"t":"Lk 2, 48-49\nSine, zašto si nam to učinio? Tvoj otac i ja žalosni smo te tražili. Zašto ste me tražili? Zar niste znali da ja moram biti u onome što pripada mom Ocu.","kn":"(Lk. 2, 48, .49). Sine, što učini nama^ tako? Evo, otac Tvoj i ja žalosni smo Te tražili! Zašto ste me tražili? Niste li znali, da meni treba biti u kući","knRef":"Kniewald 1942, str. 76–77 (snimka 39) (OCR)"},"46abd48177cf9e44":{"t":"<i>Pomolimo se</i>.\nPonizno te molimo, svemogući Bože, udijeli da ti služe i ugode dostojnijim vladanjem oni koje krijepiš svojim otajstvima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ponizno Te molimo, svemogući Bože, podaj, da Ti ugodnim vladanjem dostojno služe u životu, koje krijepiš svojim svetotajstvima, po G. n. I. K.","knRef":"Kniewald 1942, str. 98–99 (snimka 50) (OCR)"}}});
